// 轻量词/字级 diff:用于在同语言润色时,在美化后的正文里内联高亮"改了哪里"。
// 不引入第三方依赖。中文按单字切、英文等按词切,空白与标点单独成 token,兼顾中英混排。

export interface DiffPart {
  value: string;
  // added: 美化文相对原文新增/改写的片段(需要高亮);equal: 与原文一致的片段。
  type: "equal" | "added";
}

// CJK 统一表意文字(含扩展 A)+ 假名:逐字成 token;
// 其余连续的字母/数字/下划线视作一个词;空白与标点各自成 token。
function tokenize(text: string): string[] {
  const tokens: string[] = [];
  // 匹配优先级:CJK 单字 → 词(字母数字) → 空白串 → 其它单字符
  const re =
    /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]|[A-Za-z0-9]+|\s+|[^\s]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) {
    tokens.push(m[0]);
  }
  return tokens;
}

// 经典 LCS 动态规划,回溯出"哪些 token 是美化文新增的"。
// 删除片段(只在原文出现)不进入结果——正文里不展示删除,避免噪音。
export function diffWords(original: string, revised: string): DiffPart[] {
  const a = tokenize(original);
  const b = tokenize(revised);
  const n = a.length;
  const k = b.length;

  // dp[i][j] = a[i:] 与 b[j:] 的 LCS 长度
  const dp: number[][] = Array.from({ length: n + 1 }, () =>
    new Array<number>(k + 1).fill(0)
  );
  for (let i = n - 1; i >= 0; i--) {
    for (let j = k - 1; j >= 0; j--) {
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }

  const parts: DiffPart[] = [];
  const push = (value: string, type: DiffPart["type"]) => {
    const last = parts[parts.length - 1];
    if (last && last.type === type) last.value += value;
    else parts.push({ value, type });
  };

  let i = 0;
  let j = 0;
  while (i < n && j < k) {
    if (a[i] === b[j]) {
      push(b[j], "equal");
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      // a[i] 被删除:跳过,不写入正文
      i++;
    } else {
      push(b[j], "added");
      j++;
    }
  }
  while (j < k) {
    push(b[j], "added");
    j++;
  }

  return parts;
}

