import { useMemo, useState } from "react";
import type { PolishVariant } from "@/lib/types";
import { diffWords } from "@/lib/diff";

interface Props {
  variant: PolishVariant;
  index: number;
  streaming?: boolean;
  // 原文:用于同语言润色时内联高亮改动处
  original?: string;
  // 是否同语言(跨语言翻译无法逐词对比,不高亮)
  sameLanguage?: boolean;
}

export default function ResultCard({
  variant,
  index,
  streaming,
  original,
  sameLanguage,
}: Props) {
  const [copied, setCopied] = useState(false);
  const [showWhy, setShowWhy] = useState(true);
  const [showDiff, setShowDiff] = useState(true);

  // 仅同语言、非流式、有原文时才计算 diff;否则按纯文本渲染
  const canDiff = Boolean(sameLanguage && !streaming && original?.trim());
  const diffParts = useMemo(
    () => (canDiff ? diffWords(original ?? "", variant.text) : null),
    [canDiff, original, variant.text]
  );
  const highlight = canDiff && showDiff && diffParts !== null;

